(async()=>{
 const {useStudio}=await import('/src/studio/store.ts');
 const {beginGovernedWork}=await import('/src/studio/assistant/workPacketRuntime.ts');
 const {callAssistantTool}=await import('/src/studio/assistant/session.ts');
 const {loadArchitect}=await import('/src/studio/architect/persistence.ts');
 const {listWorkPackets,readWorkEvents,verifyWorkJournal}=await import('/src/studio/assistant/workPacketStore.ts');
 const id=useStudio.getState().job.id, signal=new AbortController().signal;
 let latest,executions=0,authorizations=0;
 const work=await beginGovernedWork(id,'Routing regression',{role:'user',parts:[{text:'Routing regression'}]},p=>latest=p);
 const call=(name,args)=>work.call(name,args,()=>{executions++;return callAssistantTool(name,args,signal,{allowProjectEdits:true})},async()=>{authorizations++;return null});
 const blocked=await call('draw_architect_elements',{expectedJobId:id,expectedRevision:1,operations:[]});
 if(!blocked.isError||executions||authorizations||latest.pendingAction)throw Error('Missing route reached authorization or execution');
 await call('read_workflow_route',{expectedJobId:id,workflow:'architecture'});
 await call('read_project_context',{});
 const deferred=await call('read_architect_design',{expectedJobId:id});
 if(!deferred.isError||!deferred.content[0].text.includes('navigate_workspace'))throw Error('No workspace recovery route');
 await call('navigate_workspace',{expectedJobId:id,pane:'sketch'});
 const read=await call('read_architect_design',{expectedJobId:id});
 const design=JSON.parse(read.content[0].text).project;
 const args={expectedJobId:id,expectedRevision:design.revision,operations:[{kind:'wall',levelId:design.levels[0].id,a:[0,0],b:[6000,0]}]};
 const created=await call('draw_architect_elements',args);
 if(created.isError||latest.pendingAction)throw Error('Routed mutation failed');
 const revision=loadArchitect(id,localStorage).value.revision;
 const countBefore=executions;
 const skipped=await call('draw_architect_elements',{...args,expectedRevision:revision});
 if(!skipped.isError||executions!==countBefore||latest.pendingAction)throw Error('Edit skipped current-revision readback');
 const premature=await work.reviewFinal();
 if(!premature?.includes('read_architect_design'))throw Error('Premature final not corrected');
 await call('read_architect_design',{expectedJobId:id});
 let permissionCalls=0;
 const refused=await work.call('edit_architect_elements',{expectedJobId:id,expectedRevision:revision,operations:[{kind:'set-wall',id:loadArchitect(id,localStorage).value.walls[0].id,heightMm:3100}]},async()=>{permissionCalls++;return {content:[]}},async()=> 'User declined this edit.');
 if(!refused.isError||permissionCalls||latest.pendingAction)throw Error('Permission refusal executed or created uncertainty');
 await work.finish(null);
 if(latest.state!=='blocked')throw Error('Refusal not reflected in checkpoint');
 const saved=(await listWorkPackets(id)).find(p=>p.id===latest.id),events=await readWorkEvents(saved.id);
 if(!await verifyWorkJournal(saved,events))throw Error('Journal invalid');
 return {projectId:id,packetId:saved.id,executions,authorizations,revision,wallCount:loadArchitect(id,localStorage).value.walls.length,route:saved.routing,events:events.map(e=>({kind:e.kind,sequence:e.sequence})),checks:{preflightBeforePermission:true,workspaceRecovery:true,mutationReadback:true,prematureFinal:true,permissionPreserved:true,durableJournal:true}};
})()
